HOTELS={
 'tverskaya':dict(name='Тверская',full='Туррис Тверская',address='Площадь Тверская Застава, 2, стр. 2',location='У Белорусского вокзала',tag='Семейные номера',line='Удобная отправная точка для поездок по городу и встреч в районе Тверской.',description='Начните день рядом с Белорусским вокзалом. В Тверской можно выбрать категорию с двуспальной или двумя отдельными кроватями, а для семейной поездки — рассмотреть семейный люкс. Сравните варианты по составу гостей и проверьте тариф на свои даты.',focus='Выбор кроватей и семейный люкс',notice='Завтрак, дополнительные места и условия заезда уточняйте для выбранного тарифа.',email='m-br-1@turris-management.ru',slug='turris-hotel-tverskaya'),
 'lubyansky':dict(name='Лубянский',full='Туррис Лубянский',address='Лубянский проезд, 19, стр. 2',location='Рядом с Китай-городом и Зарядьем',tag='Категории с диваном',line='Для прогулок по историческому центру и поездок без лишних пересадок.',description='Лубянский — адрес для тех, кто хочет проводить больше времени в городе. В номерном фонде есть стандартные категории, варианты Deluxe с разными кроватями и номера с раскладывающимся диваном. У Duplex два уровня: обратите внимание на внутреннюю лестницу при выборе для ребёнка или гостя с ограниченной подвижностью.',focus='От одноместного номера до Duplex',notice='Номер Duplex имеет два уровня. Питание и парковка зависят от условий бронирования.',email='m-tur-1@turris-management.ru',slug='turris-hotel-lubyansky-'),
 'petrovsky':dict(name='Петровский',full='Туррис Петровский',address='Петровский бульвар, 9, стр. 1',location='На Петровском бульваре',tag='Предложение от 21 дня',line='Городская поездка или более долгий срок — с одной привычной точкой возвращения.',description='Отель на Петровском бульваре подойдёт для знакомства с центром Москвы и поездки на несколько недель. Выбирайте между стандартной, улучшенной и мансардными категориями. У мансарды свой характер: перед бронированием посмотрите фотографии скосов и расположения кровати.',focus='Четыре категории и длительное проживание',notice='В мансардных категориях есть скосы потолка. Условия проживания от 21 дня подтверждает отель.',email='m-br-1@turris-management.ru',slug='turris-hotel-petrovsky'),
 'tagansky':dict(name='Таганский',full='Туррис Таганский',address='Серебрянический переулок, 15',location='Рядом с набережной',tag='Историческое здание · без лифта',line='Московские переулки, набережная и свой ритм поездки.',description='Таганский расположен в Серебряническом переулке. Здесь можно выбрать категорию с одной двуспальной или двумя раздельными кроватями, а также мансардный вариант. В здании нет лифта: если вы путешествуете с коляской или тяжёлым багажом, заранее уточните этаж и возможность помощи.',focus='Выбор кроватей; важное условие — нет лифта',notice='В отеле нет лифта. Завтрак включён не во все тарифы: проверяйте состав выбранного предложения.',email='m-br-1@turris-management.ru',slug='turris-hotel-tagansky'),
}
FAQ=[
 ('Можно ли изменить или отменить бронирование?','Это зависит от выбранного тарифа. До оплаты проверьте срок бесплатной отмены, размер возможного удержания и способ изменения дат. Условия вашей брони указаны в подтверждении.','help_cancel'),
 ('Входит ли завтрак в стоимость?','Не во все тарифы. Сравнивайте предложения на одинаковые даты и состав гостей: рядом с ценой должно быть указано питание. В Таганском доступны варианты как с завтраком, так и без него.','payment'),
 ('Как выбрать номер для поездки с детьми?','Укажите возраст каждого ребёнка и посмотрите, какие спальные места предусмотрены в категории. Диван, дополнительная кровать и детская кроватка — разные варианты, их наличие и оплату нужно уточнить до бронирования.','family'),
 ('Можно ли приехать с питомцем?','Размещение с животными нужно согласовать с конкретным отелем. Сообщите вид, размер питомца и даты поездки; уточните ограничения, доплату и необходимость специального тарифа.','help_pets'),
 ('Где есть парковка и лифт?','Эти условия различаются по объектам. В Таганском нет лифта. Возможность парковки, стоимость, въезд и резерв места уточняйте в выбранном отеле до приезда.','contacts'),
 ('Возможен ли ранний заезд или поздний выезд?','Такие условия подтверждаются отдельно и зависят от наличия свободных номеров. Позднее прибытие ночью и поздний выезд — разные ситуации: обязательно сообщите время поездки.','help_checkin'),
 ('Как оплатить проживание от компании?','Перед оплатой сообщите данные плательщика, даты, состав гостей и требования к документам. Менеджер уточнит возможность безналичной оплаты и порядок оформления.','business'),
]

# Original editorial demo copy. No invented walking times, prices, field research or travel experience.
ARTICLES={
 'choose-area':dict(answer='Выбирайте район по адресам, которые будете посещать чаще всего. Близость к нужному месту обычно полезнее, чем абстрактное обещание «самого центра»: сравните путь от входа в отель до конкретной точки поездки.',sections=[
 ('Начните с трёх адресов','Запишите место встречи, главный пункт прогулки и вокзал или аэропорт отправления. Постройте маршруты от каждого подходящего отеля. Смотрите не только расстояние по прямой: переходы, выход из метро и багаж могут заметно изменить удобство пути.'),
 ('Четыре разных отправных точки','Тверская находится на площади Тверская Застава; Лубянский — в Лубянском проезде; Петровский — на Петровском бульваре; Таганский — в Серебряническом переулке. Сравните эти адреса с вашим планом, а затем переходите к категории номера.'),
 ('Проверьте повседневные детали','Для семьи важны спальные места и доступность здания, для командировки — документы и условия оплаты. В Таганском нет лифта; у мансардных категорий Петровского и Таганского есть скосы потолка. Такие особенности лучше учесть раньше, чем сравнивать фотографии.'),
 ('Оставьте запас на город','Не стройте план по минимальному времени в карте. Сохраните адрес входа, телефон отеля и запасной вариант маршрута. Расписания транспорта и режим работы мест проверяйте перед выездом.')]),
 'tverskaya-walk':dict(answer='Для прогулки от Тверской удобно начать с площади Тверская Застава и выбрать направление вдоль Тверской-Ямской улицы. Длину прогулки определяйте по погоде и собственному темпу, а обратный путь сохраните в карте.',sections=[
 ('Старт у вашего отеля','Адрес Тверской — площадь Тверская Застава, 2, стр. 2. Перед выходом отметьте вход в телефоне: точка дома и фактическая дверь могут отличаться. Возьмите контакт отеля, если планируете возвращаться поздно.'),
 ('Прогулка по интересам','Вместо списка обязательных остановок выберите одну тему: городская архитектура, фотографии или кафе с возможностью отдохнуть. Тверская-Ямская улица позволяет постепенно двигаться в сторону центральных кварталов; конкретный поворот и переход проверяйте по карте.'),
 ('Не перегружайте день','С ребёнком или после дороги лучше сделать короткую прогулку и вернуться в номер. Билеты, часы посещения и доступность нужных мест проверяйте на их официальных страницах. Не ориентируйтесь на старые подборки расписаний.'),
 ('Продумайте возвращение','Сохраните маршрут до отеля до выхода. Если путешествуете с чемоданом, отдельно проверьте путь от вокзала: удобный прогулочный маршрут не всегда подходит для багажа.')]),
 'lubyanka-walk':dict(answer='От Лубянского можно спланировать прогулку по историческому центру: выберите одну основную цель в районе Китай-города или Зарядья и стройте путь от фактического входа в отель.',sections=[
 ('Опорная точка','Отель расположен по адресу Лубянский проезд, 19, стр. 2. Сохраните адрес и телефон, затем отметьте нужную точку на карте. Время пути рассчитывайте для пешеходного маршрута, а не по расстоянию между адресами.'),
 ('Один маршрут — одна задача','Для спокойной прогулки достаточно одного района и нескольких интересных остановок. Если цель — парк Зарядье, заранее посмотрите программу и режим нужных пространств на официальном сайте. План посещения музея лучше строить вокруг времени входного билета.'),
 ('Условия важнее красивого списка','Проверьте погоду, удобные переходы и возможность остановиться. Для коляски отдельно уточните лестницы и доступные входы. В этой подборке нет обещания одинакового времени пути для всех гостей.'),
 ('Вернитесь своим темпом','Номер выбирайте с учётом того, как будете отдыхать после прогулки. Если нужен диван или отдельные кровати, посмотрите конкретную категорию Лубянского, а не только общую фотографию отеля.')]),
 'taganka-walk':dict(answer='Прогулку от Таганского лучше строить от Серебрянического переулка: сначала выберите набережную или городские кварталы как основную цель, затем проверьте пешеходный путь и переходы.',sections=[
 ('Где начинается прогулка','Адрес отеля — Серебрянический переулок, 15. Отметьте вход перед выходом и сохраните контакт службы размещения. С багажом или коляской учитывайте, что в здании отеля нет лифта.'),
 ('Выберите направление','Для первой прогулки можно рассмотреть набережную и соседние переулки. Не объединяйте слишком много удалённых точек: оставьте возможность сократить маршрут или вернуться в номер.'),
 ('Проверьте условия пути','Наличие лестниц, переходов и ремонтных ограждений лучше уточнить по актуальной карте. Не считайте обозначенный здесь вариант проверенным безбарьерным маршрутом: доступность зависит от конкретного пути.'),
 ('Запасной план на дождь','Заранее выберите помещение, куда удобно зайти по пути, и проверьте его часы работы. Если день занят встречами, прогулку можно оставить на короткий свободный промежуток, без обязательного количества остановок.')]),
 'petrovsky-walk':dict(answer='Петровский бульвар — понятная отправная точка для прогулки по центральным бульварам. Начните с адреса отеля и выберите короткий участок, который удобно пройти туда и обратно.',sections=[
 ('Сохраните точку возвращения','Туррис Петровский находится по адресу Петровский бульвар, 9, стр. 1. Запишите именно этот адрес, а не только название сети. Перед поздним возвращением согласуйте детали прибытия с отелем.'),
 ('Планируйте маршрут участками','Выберите следующий бульвар или конкретное место как ориентир. Пешеходные переходы и фактическое расстояние проверьте в карте. Небольшой маршрут можно продлить по настроению, а длинный план сложнее сократить без лишних переездов.'),
 ('Учитывайте цель поездки','При командировке оставляйте запас перед встречей. Если приехали на несколько недель, сначала изучите ближайшие ежедневные маршруты: работу, транспорт и удобные места для отдыха.'),
 ('Проверьте номер до оплаты','Мансардные категории отличаются потолком и расположением окон. Посмотрите фото конкретного варианта; для длительного проживания уточните уборку, продление и порядок расчёта, а не только стартовую стоимость.')]),
 'family-room-checklist':dict(answer='Семейный номер выбирают по фактическим спальным местам и возрасту детей. Сначала определите состав гостей, затем проверьте кровати, дополнительные места, лестницы и условия питания.',sections=[
 ('Люди и кровати — не одно и то же','Указание «двухместный» не объясняет, можно ли добавить ребёнка. Узнайте, где будет спать каждый гость: на основной кровати, диване, дополнительном месте или в детской кроватке. У каждого варианта могут быть свои ограничения и стоимость.'),
 ('Возраст нужно указать заранее','При поиске заполните возраст каждого ребёнка. Если вы сравниваете предложения на разных сайтах, состав гостей должен совпадать. Иначе разница в цене может объясняться не скидкой, а другим размещением.'),
 ('Проверьте здание и планировку','В Таганском нет лифта, а Duplex Лубянского — двухуровневый номер. Это не запрещает семейную поездку, но требует осознанного выбора. Для семейного люкса Тверской уточните состав спальных мест и доступность на ваши даты.'),
 ('Что спросить до оплаты','Нужны ли доплата за ребёнка и отдельный завтрак? Есть ли кроватка и подтверждено ли её предоставление? Можно ли оставить багаж до заселения? Ответы стоит получить до выбора невозвратного тарифа.')]),
 'moscow-with-child':dict(answer='Для поездки с ребёнком удобнее план с одной основной целью на день и возможностью вернуться в отель. Начните с возраста, режима отдыха и допустимого времени в дороге.',sections=[
 ('Сначала ритм, потом достопримечательности','Определите, когда нужен сон, еда и спокойная пауза. Не заполняйте все свободные часы: переезды и ожидание входа тоже занимают силы. Выберите одну обязательную цель, остальные оставьте дополнительными.'),
 ('Маршрут с коляской проверяется отдельно','Уточните доступный вход, лестницы и переходы на пути. В отеле Таганский нет лифта; в двухуровневых номерах нужно учитывать внутреннюю лестницу. Помощь с багажом и место для коляски согласуйте заранее.'),
 ('Номер должен подходить всем','Возраст детей влияет на подбор. Проверьте реальные спальные места, а не только максимальную вместимость. Диван или кроватка должны быть подтверждены, если вы рассчитываете на них во время поездки.'),
 ('Держите запасной вариант','На случай дождя выберите более короткую прогулку или помещение поблизости. Часы работы и правила посещения проверяйте перед выходом. План должен помогать семье, а не требовать выполнить каждую остановку.')]),
 'trip-documents':dict(answer='До оплаты командировки уточните у работодателя требования к документам и передайте их отелю. Не существует одного списка, который подходит каждой компании и каждому способу расчёта.',sections=[
 ('Что узнать у бухгалтерии','Уточните, кто оплачивает проживание, на кого оформляются документы и какие сведения должны быть в них указаны. Отдельно спросите о питании и дополнительных услугах: порядок их учёта может отличаться.'),
 ('Что сообщить отелю','Передайте даты, имя гостя, данные плательщика и нужный способ оплаты. Попросите подтвердить, какие документы отель выдаёт в вашей ситуации и когда их можно получить. Это особенно важно при оплате компанией.'),
 ('Изменение дат тоже влияет на документы','Если поездка переносится или сокращается, свяжитесь с отелем до изменения брони. Отмена и перерасчёт зависят от тарифа. Сохраните подтверждения договорённостей вместе с исходным бронированием.'),
 ('Чего не стоит предполагать','Не считайте любую электронную квитанцию достаточной для отчёта. Проверяйте требования своей организации и подтверждение отеля. Этот материал помогает подготовить вопросы, но не заменяет правила бухгалтерии или правовую консультацию.')]),
 'business-location':dict(answer='Отель для командировки выбирайте по маршруту встреч, а не только по району. Сравните поездки утром и вечером, затем проверьте документы, питание и удобство работы в номере.',sections=[
 ('Соберите рабочую карту','Добавьте адреса встреч и время начала. Проверьте варианты транспорта с учётом дня недели. Не закладывайте минимальное время в пути как гарантированное: пробки и пересадки меняют план.'),
 ('Выберите подходящий адрес Туррис','Тверская, Лубянский, Петровский и Таганский находятся в разных частях центра. Возьмите точные адреса из контактов и сравните маршрут до места вашей работы. Общая формулировка «в центре» не заменяет такого сравнения.'),
 ('Уточните ежедневные условия','Если планируете работать в номере, спросите о столе и расположении розеток в выбранной категории. Наличие подключения к интернету не является гарантией конкретной скорости. Завтрак и его время также нужно сверить с рабочим графиком.'),
 ('Выберите способ оформления','Для личной поездки можно перейти к обычной брони. Если оплачивает организация или приезжают несколько сотрудников, заранее отправьте запрос менеджеру и требования к документам.')]),
 'group-organizer':dict(answer='Хороший запрос на группу содержит даты, число гостей, желаемое распределение по комнатам и требования к питанию. Контакт организатора нужен для согласования; персональные данные всех участников на первом шаге не требуются.',sections=[
 ('Даты и гибкость','Укажите заезд, выезд и возможное смещение дат. Если группа приезжает несколькими рейсами, сообщите это отдельно. Гибкость помогает менеджеру предложить подходящее распределение, но не гарантирует наличие.'),
 ('Комнаты и состав','Опишите, сколько нужно одноместных, двухместных и других вариантов, есть ли дети и какие кровати важны. Если размещение в нескольких объектах допустимо, сообщите об этом сразу.'),
 ('Что включить в расчёт','Уточните питание, способ оплаты, документы, сроки внесения средств и правила изменения состава. Сравнивайте предложения по полной сумме и одинаковому набору услуг.'),
 ('После ответа менеджера','Проверьте распределение по отелям и категориям, срок действия предложения и порядок подтверждения. Полученная заявка ещё не означает, что номера забронированы: это отдельный этап согласования.')]),
 'attic-room':dict(answer='Мансардный номер расположен под крышей и может иметь скошенный потолок. До бронирования посмотрите высоту и проходы возле кровати, расположение окна и фотографии именно выбранной категории.',sections=[
 ('Что отличает мансарду','Главное отличие — геометрия помещения. Скос может находиться над частью кровати, зоной отдыха или проходом. Общая площадь сама по себе не объясняет, насколько удобно пользоваться каждым участком комнаты.'),
 ('Какие фото нужны','Посмотрите общий вид, подход к кровати, потолок и окно. Если что-то неясно, попросите отель уточнить детали. Вид из окна не следует предполагать по атмосферной фотографии другого помещения.'),
 ('Какие категории есть в Туррис','Мансардные варианты представлены в Петровском и Таганском. Duplex Лубянского — двухуровневая категория, но это не повод автоматически называть её мансардой. Разные особенности требуют разных вопросов.'),
 ('Когда стоит выбрать другой вариант','Если важны одинаковая высота потолка, свободное перемещение или отсутствие лестниц, сначала уточните планировку. В Таганском дополнительно учитывайте отсутствие лифта. Подходящий номер выбирается по вашим условиям, а не по названию категории.')]),
 'twin-double':dict(answer='Twin обычно обозначает две отдельные кровати, Double — одну двуспальную. Но тип кровати и допустимое число гостей — разные характеристики: диван и дополнительное место нужно проверять отдельно.',sections=[
 ('Название — начало проверки','Посмотрите описание конкретной категории. Если указана одна двуспальная или две раздельные кровати, уточните, можно ли гарантировать нужную конфигурацию при бронировании. Комментарий к заявке не всегда означает подтверждённый выбор.'),
 ('Диван не равен ещё двум местам','Уточните, раскладывается ли диван, какова его вместимость и включено ли размещение на нём в тариф. Если едет ребёнок, важен его возраст. Не прибавляйте места самостоятельно по фотографии.'),
 ('Сравнивайте одинаковый состав','В одном поиске задайте всех взрослых и детей. Так итоговая сумма будет относиться к вашей поездке. При изменении состава гостей цена и доступные категории могут измениться.'),
 ('Где смотреть в Туррис','В Тверской есть отдельные категории с двумя кроватями, в Лубянском — Twin и варианты с диваном. Для Таганского конфигурацию кроватей нужно уточнять в выбранной категории. Переходите к конкретному номеру, чтобы не потерять выбор.')]),
 'breakfast-rates':dict(answer='Тарифы с завтраком и без него сравнивают на одинаковые даты, срок и состав гостей. Посмотрите полную сумму, питание для детей и условия отмены: более низкая цена может относиться к другому набору условий.',sections=[
 ('Сначала выровняйте параметры','Укажите один и тот же отель, категорию, даты и гостей. Если сравнивать разные номера или сроки, невозможно понять, сколько стоит именно включение завтрака.'),
 ('Проверьте, кому включено питание','Завтрак взрослого и питание ребёнка могут оплачиваться по-разному. Уточните возрастные условия и число завтраков. В Таганском наличие завтрака зависит от выбранного тарифа.'),
 ('Сверьте время с поездкой','При раннем выезде или утренней встрече уточните расписание. Возможность другого формата питания нужно согласовывать, а не предполагать. Информация о завтраке должна относиться к конкретному объекту.'),
 ('Не забывайте про отмену','Два предложения могут различаться предоплатой и возвратностью. Сравните итоговую сумму вместе с риском изменения поездки. Условия сохраняются в подтверждении вашей брони.')]),
 'long-stay-checklist':dict(answer='Для проживания от трёх недель важны не только цена, но и уборка, рабочее место, оплата и правила продления. До подтверждения получите условия на весь срок и узнайте, что произойдёт при изменении дат.',sections=[
 ('Проверьте бытовой ритм','Уточните частоту уборки и смены белья, хранение вещей и дополнительные услуги. Не считайте кухню, стирку или рабочую зону включёнными только потому, что выбираете длительный срок.'),
 ('Посмотрите категорию подробнее','Оцените спальные места, хранение вещей и геометрию комнаты. У Петровского есть мансардные категории: если планируете провести в номере много времени, заранее изучите скосы и расположение окна.'),
 ('Получите полный расчёт','Укажите начало и окончание проживания, состав гостей и нужные услуги. Уточните сумму, график оплаты и условия досрочного выезда. Опубликованное предложение от 21 дня в Петровском нужно подтвердить на конкретные даты.'),
 ('Продление не всегда автоматическое','Обсудите, когда сообщить о продлении и будет ли доступна та же категория. Если планы пока меняются, скажите об этом менеджеру до выбора тарифа.')]),
 'arrival-checklist':dict(answer='Позднее прибытие, раннее заселение и поздний выезд — разные запросы. Сообщите отелю точное время приезда и проверьте, какой срок проживания и какие дополнительные условия вам нужны.',sections=[
 ('Если приезжаете ночью','Проверьте дату, с которой должен быть забронирован номер. Прибытие после полуночи легко перепутать с обычным дневным заселением этой даты. Свяжитесь с отелем и подтвердите, что номер будет ожидать вас.'),
 ('Если хотите заселиться раньше','Ранний заезд зависит от наличия и условий объекта. Не рассчитывайте на него только по времени прибытия поезда. Возможность оставить багаж — отдельный вопрос, который тоже следует уточнить.'),
 ('Если выезжаете позже','Сообщите желаемое время и спросите о стоимости и сроке подтверждения. Поздний выезд не следует считать включённым в любую программу лояльности или тариф без проверки правил.'),
 ('Что сохранить перед дорогой','Подтверждение брони, точный адрес входа, контакт отеля и согласованные условия. Если поезд задерживается, сообщите об изменении планов, чтобы избежать недоразумений с прибытием.')]),
 'hotel-pets-checklist':dict(answer='Поездку с питомцем согласуйте с конкретным отелем до оплаты. Наличие предложения о размещении с животными не означает, что разрешены любые животные, размеры и даты без доплаты.',sections=[
 ('Опишите питомца и поездку','Сообщите вид, размер и количество животных, даты и состав гостей. Уточните, требуется ли особая категория или тариф и какие ограничения действуют в помещениях отеля.'),
 ('Проверьте полную стоимость','Спросите о доплате, депозите и дополнительных условиях уборки. Не ориентируйтесь только на заголовок старой акции: её срок и применимость нужно подтвердить на вашу поездку.'),
 ('Получите подтверждение','Сохраните ответ отеля вместе с бронированием. Если информация на разных площадках расходится, уточните актуальное правило непосредственно у объекта. Условия одного отеля сети не распространяются автоматически на остальные.'),
 ('Планируйте повседневные детали','Уточните доступные зоны, возможность оставлять животное в номере и необходимые принадлежности. Это поможет избежать ситуации, когда формально разрешённое размещение не подходит вашему режиму поездки.')]),
}

HELP={
 'help_booking':('Как забронировать номер', 'Выберите отель, даты и состав гостей. Затем сравните категории и тарифы, проверьте питание и отмену и переходите к оформлению.', [('1. Укажите поездку','Добавьте всех взрослых и детей с возрастом. Выбранные даты и состав влияют на доступность и итоговую стоимость.'),('2. Проверьте категорию','Сопоставьте кровати, дополнительные места и особенности здания. У мансардных номеров посмотрите скосы, у Duplex — лестницу.'),('3. Изучите тариф','Питание, предоплата и отмена должны быть понятны до оплаты. Сохраните условия и подтверждение брони.'),('Если подтверждение не пришло','Проверьте почту и папку нежелательных писем, затем свяжитесь с отелем. Не повторяйте оплату, пока не выяснен статус первого платежа.')]),
 'help_cancel':('Изменение и отмена брони','Откройте подтверждение бронирования: в нём указаны условия вашего тарифа и способ управления. Возврат и возможные удержания зависят от этих условий.', [('Сначала прочитайте условия','Найдите срок отмены без удержания и правила после его окончания. Не переносите условия одного тарифа на другой.'),('Если меняются даты','Согласуйте изменение с отелем или через поддерживаемый способ управления бронью. На новые даты могут действовать другие цены и наличие.'),('Если нужен возврат','Уточните порядок и статус возврата у отеля или платёжного провайдера. Не сообщайте реквизиты карты через общедоступные формы.'),('Бронировали на другой площадке','Начните с подтверждения той площадки, где была оформлена бронь. Процедура может отличаться от прямого бронирования.')]),
 'help_checkin':('Заезд и выезд','Время заселения и выезда проверяйте в подтверждении конкретного отеля. Ранний заезд и поздний выезд согласуются отдельно и зависят от наличия.', [('До дороги','Проверьте дату начала проживания, особенно если приезжаете после полуночи. Сохраните адрес входа и телефон.'),('При позднем прибытии','Сообщите ожидаемое время и попросите подтвердить порядок входа и заселения. Уточните условия сохранения номера.'),('Документы','Уточните необходимые документы для вашего состава гостей, включая детей. Не отправляйте их фотографии через демонстрационную форму.'),('Багаж и этаж','Если важны лифт, отсутствие лестниц или хранение багажа, согласуйте это заранее. В Таганском нет лифта.')]),
 'help_children':('Проживание с детьми','Укажите возраст каждого ребёнка при поиске и проверьте, где будет спать каждый гость. Возможность дополнительного места или кроватки подтверждается отдельно.', [('Состав семьи','Количество мест зависит от категории и возраста детей. Не делайте вывод о вместимости только по фотографии кровати.'),('Питание','Проверьте, включён ли завтрак ребёнка и нужна ли доплата. Эти условия могут отличаться от питания взрослых.'),('Планировка','Оцените лестницы, этаж и мансардные скосы. Семейный люкс Тверской и варианты с диваном Лубянского стоит сравнить по реальным спальным местам.'),('Перед оплатой','Получите подтверждение нужного размещения и дополнительных принадлежностей. Выберите тариф с подходящими условиями изменения поездки.')]),
 'help_pets':('Поездка с питомцем','До бронирования свяжитесь с выбранным отелем. Сообщите вид и размер животного, даты и уточните ограничения, доплату и необходимость отдельного тарифа.', [('Условия конкретного объекта','Не считайте правила всей сети одинаковыми. Даже если предложение есть на сайте, его действие нужно проверить на ваши даты.'),('Что уточнить','Количество питомцев, допустимые размеры, документы, ограничения по зонам, уборка и возможность оставлять животное в номере.'),('Если сведения расходятся','Ориентируйтесь на подтверждённый ответ выбранного отеля. Сохраните его вместе с условиями бронирования.'),('Подготовка к поездке','Согласуйте нужные принадлежности и порядок прибытия. Не оплачивайте невозвратный тариф до подтверждения размещения с питомцем.')]),
 'payment':('Оплата проживания','Способ и срок оплаты зависят от выбранного тарифа. Перед подтверждением проверьте полную сумму, включённые услуги, предоплату и условия отмены.', [('Полная стоимость','Сравнивайте цены на одинаковые даты, категорию и состав гостей. Питание и дополнительные места могут менять итог.'),('Оплата онлайн','Используйте защищённый платёжный переход из официального процесса бронирования. В этом прототипе нет приёма платежей или полей банковской карты.'),('Оплата от компании','До оформления передайте менеджеру данные плательщика и требования к документам. Уточните порядок безналичного расчёта.'),('Платёж прошёл, а письма нет','Сначала выясните статус операции у отеля. Не повторяйте оплату, пока не получите ответ по первой попытке.')]),
}
